"""Clone a repo at a SHA in a fresh container, repair install/build failures with the agent
loop, then prove the fix in a second fresh container.

Usage: uv run python -m resurgo.run <owner/repo> <sha> [--path <subdir>]
"""
import argparse
import contextlib
import json
import os
import shlex
import subprocess
import sys
import time
from datetime import datetime, timezone
from pathlib import Path

import neatlogs
from dotenv import load_dotenv

from resurgo import __version__
from resurgo.agent import BUDGET_S, build_graph
from resurgo.gateway import GatewayChat
from resurgo.rules import BASELINE_NODE, LOCKFILES, RULE_FILES, parse_major

IMAGE = "node:24-bookworm"
NETWORK = "resurgo-runs"
STEP_TIMEOUT = 900
TAIL_LINES = 60
LIMITS = ["--cpus", "2", "--memory", "4g", "--pids-limit", "512",
          "--cap-drop", "ALL", "--security-opt", "no-new-privileges"]
# Frozen and regenerating install commands per package manager.
INSTALL = {"pnpm": ("pnpm install --frozen-lockfile", "pnpm install --no-frozen-lockfile"),
           "yarn": ("yarn install --frozen-lockfile", "yarn install"),
           "yarn-berry": ("yarn install --immutable", "yarn install --no-immutable"),
           "npm": ("npm ci", "npm install")}
ENV_PREFIX = ('export PATH="$HOME/.pm/node_modules/.bin:$HOME/.node/node_modules/.bin:'
              '$HOME/.local/bin:$PATH" COREPACK_ENABLE_DOWNLOAD_PROMPT=0; ')


def detect_pm(files):
    for name, pm in LOCKFILES:
        if name in files:
            return pm
    return None


def scrub(text):
    """Never let the Docker host or model gateway address reach output or files."""
    for var in ("DOCKER_HOST", "MODEL_GATEWAY_URL"):
        host = os.environ.get(var, "")
        bare = host.split("://")[-1].rstrip("/")
        for secret in (host, bare, bare.rsplit(":", 1)[0].split("/")[0]):
            if secret:
                text = text.replace(secret, f"<{var.lower().replace('_', '-')}>")
    return text


def docker(*args, timeout=60):
    p = subprocess.run(["docker", *args], capture_output=True, text=True, timeout=timeout)
    return p.returncode, scrub(p.stdout + p.stderr)


def exec_raw(container, cmd, data=None, timeout=120):
    """(exit code, stdout, stderr) of a command in the container; `data` goes to stdin."""
    # input="" closes stdin at once; without it `exec -i` waits on the parent's stdin
    p = subprocess.run(["docker", "exec", "-i", "-u", "node", "-w", "/home/node", container,
                        "bash", "-c", cmd], input=data or "", capture_output=True, text=True,
                       errors="replace", timeout=timeout)
    return p.returncode, p.stdout, scrub(p.stderr)


def step(name, container, cmd, timeout=STEP_TIMEOUT):
    t0, w0 = time.time(), time.monotonic()
    try:
        code, out = docker("exec", "-u", "node", "-w", "/home/node", container,
                           "bash", "-c", ENV_PREFIX + cmd, timeout=timeout)
    except subprocess.TimeoutExpired:
        code, out = -1, f"timed out after {timeout}s"
    rec = {"name": name, "command": cmd, "exit_code": code,
           "duration_s": round(time.monotonic() - w0, 1), "started": t0, "ended": time.time(),
           "output_tail": out.splitlines()[-TAIL_LINES:]}
    print(f"  [{container.rsplit('-', 1)[-1]}] {name}: exit {code} in {rec['duration_s']}s", flush=True)
    return rec, out


def start_container(name, run_id):
    code, out = docker("run", "-d", "--name", name, "--label", f"resurgo.run={run_id}",
                       "--network", NETWORK, *LIMITS, "--user", "node", IMAGE, "sleep", "infinity",
                       timeout=600)
    if code:
        raise RuntimeError(f"docker run failed: {out.strip()}")


TRACING = False


class _NoSpan:
    def set_attribute(self, key, value):
        pass


def tool_span(name):
    if TRACING:
        return neatlogs.trace(name, kind="TOOL")
    return contextlib.nullcontext(_NoSpan())


def tool_span_root():
    if TRACING:
        return neatlogs.trace("resurgo.run", kind="WORKFLOW")
    return contextlib.nullcontext(_NoSpan())


class Box:
    """One container holding a clone of the repo; the project lives in `subdir` of the clone."""

    def __init__(self, container, role, subdir="", deadline=None):
        self.container, self.role, self.subdir, self.deadline = container, role, subdir, deadline
        self.steps = []
        self.pm = self.install_dir = None
        self.has_build = False
        self.frozen = True        # False once a lockfile was removed to be regenerated
        self.versions = ""
        self.last_out = ""
        self.touched = []         # repo-relative paths the agent wrote or removed

    @property
    def proj(self):
        return f"repo/{self.subdir}" if self.subdir else "repo"

    def rel(self, name):
        return f"{self.subdir}/{name}" if self.subdir else name

    def sh(self, name, cmd):
        timeout = STEP_TIMEOUT
        if self.deadline:
            timeout = int(max(30, min(STEP_TIMEOUT, self.deadline - time.monotonic())))
        with tool_span(f"{self.role}.{name}") as sp:
            rec, out = step(name, self.container, cmd, timeout)
            self.steps.append(rec)
            tail = "\n".join(rec["output_tail"])
            sp.set_attribute("neatlogs.tool.name", f"{self.role}.{name}")
            sp.set_attribute("command", cmd)
            sp.set_attribute("exit_code", rec["exit_code"])
            sp.set_attribute("duration_s", rec["duration_s"])
            sp.set_attribute("output_tail", tail)
            if rec["exit_code"]:
                sp.set_attribute("neatlogs.tool.is_error", True)
                sp.set_attribute("error", tail.splitlines()[-1] if tail else f"exit {rec['exit_code']}")
        self.last_out = out
        return rec["exit_code"] == 0

    def read(self, path):
        code, out, _ = exec_raw(self.container, f"cat {shlex.quote('repo/' + path)}")
        return out if code == 0 else None

    def read_many(self, paths):
        """{path: content} for the repo-relative paths that exist, in one container call."""
        quoted = " ".join(shlex.quote(p) for p in paths)
        script = (f'cd repo && for f in {quoted}; do [ -f "$f" ] && '
                  f'{{ printf "\\0FILE %s\\0" "$f"; cat "$f"; }}; done; true')
        _, out, _ = exec_raw(self.container, script)
        files = {}
        for chunk in out.split("\0FILE ")[1:]:
            path, _, text = chunk.partition("\0")
            files[path] = text
        return files

    def write(self, files):
        for path, content in files.items():
            q = shlex.quote("repo/" + path)
            code, _, err = exec_raw(self.container, f"mkdir -p \"$(dirname {q})\" && cat > {q}", content)
            if code:
                raise RuntimeError(f"write {path} failed: {err.strip()}")
            self.touched.append(path)
        return list(files)

    def remove(self, paths):
        for path in paths:
            exec_raw(self.container, f"rm -f {shlex.quote('repo/' + path)}")
            self.touched.append(path)
            self.frozen = False
        return paths

    def rule_files(self):
        """Contents of the files the rules read: project dir first, repo root as fallback
        (never for package.json)."""
        files, self.where = {}, {}
        found = self.read_many([p for n in RULE_FILES for p in {self.rel(n), n}])
        for name in RULE_FILES:
            for path in dict.fromkeys([self.rel(name), name]):
                if path in found:
                    files[name], self.where[name] = found[path], path
                    break
                if name == "package.json":
                    break
        return files

    def clone(self, repo, sha):
        check = f" && test -d {shlex.quote(self.subdir)}" if self.subdir else ""
        return self.sh("clone", f"git clone -q https://github.com/{repo}.git repo && cd repo "
                                f"&& git checkout -q {sha}{check}")

    def apply_patch(self, patch):
        code, _, err = exec_raw(self.container, "cd repo && git apply --whitespace=nowarn -", patch)
        if code:
            raise RuntimeError(f"patch did not apply: {err.strip()}")

    def diff(self):
        """Patch of the files the agent touched, new files included."""
        paths = " ".join(shlex.quote(p) for p in dict.fromkeys(self.touched))
        if not paths:
            return ""
        _, out, _ = exec_raw(self.container, f"cd repo && git add -N -- {paths} 2>/dev/null; "
                                             f"git diff --no-color --no-ext-diff -- {paths}")
        return out

    def toolchain_cmd(self, files):
        """Node major from .nvmrc (24 otherwise) and an npm pin; pnpm and yarn come from
        corepack, which honours the packageManager field itself."""
        major = parse_major(files.get(".nvmrc")) or BASELINE_NODE
        cmd = "mkdir -p $HOME/.local/bin && corepack enable --install-directory $HOME/.local/bin"
        cmd += (f" && npm install --prefix $HOME/.node node@{major}" if major != BASELINE_NODE
                else " && rm -rf $HOME/.node")
        try:
            declared = json.loads(files.get("package.json") or "{}").get("packageManager", "")
        except ValueError:
            declared = ""
        if declared.startswith("npm@"):
            cmd += f" && npm install --prefix $HOME/.pm npm@{declared[4:].split('+')[0]}"
        else:
            cmd += " && rm -rf $HOME/.pm"
        return cmd + " && node --version"

    def detect(self, files):
        found = detect_pm(files)
        rec = {"name": "detect", "command": "lockfile", "exit_code": 0 if found else 1,
               "duration_s": 0, "package_manager": found,
               "output_tail": [] if found else ["no pnpm/yarn/npm lockfile found"]}
        self.steps.append(rec)
        self.last_out = "\n".join(rec["output_tail"])
        if not found:
            return False
        lock = {"pnpm": "pnpm-lock.yaml", "yarn": "yarn.lock", "npm": "package-lock.json"}[found]
        self.pm = found
        if found == "yarn" and "__metadata:" in files[lock]:
            self.pm = "yarn-berry"
        self.install_dir = f"repo/{self.where[lock].rsplit('/', 1)[0]}" if "/" in self.where[lock] else "repo"
        try:
            self.has_build = "build" in (json.loads(files.get("package.json") or "{}").get("scripts") or {})
        except ValueError:
            self.has_build = False
        return True

    def pipeline(self):
        """toolchain, detect, install, then build if the project has a build script.
        Returns None when everything passes, else {step, command, exit_code}."""
        def failure(name):
            rec = self.steps[-1]
            return {"step": name, "command": rec["command"], "exit_code": rec["exit_code"]}

        files = self.rule_files()
        if not self.sh("toolchain", self.toolchain_cmd(files)):
            return failure("toolchain")
        self.versions = f"node {self.last_out.strip().splitlines()[-1]}" if self.last_out.strip() else ""
        if self.pm is None and not self.detect(files):
            return failure("detect")
        pm = self.pm.split("-")[0]
        install = INSTALL[self.pm][0 if self.frozen else 1]
        if not self.sh("install", f"cd {self.install_dir} && {pm} --version && {install}"):
            return failure("install")
        if self.has_build and not self.sh("build", f"cd {self.proj} && {pm} run build"):
            return failure("build")
        return None


def ensure_network():
    if docker("network", "inspect", NETWORK)[0]:
        code, out = docker("network", "create", NETWORK)
        if code:
            raise RuntimeError(f"network create failed: {out.strip()}")


def init_tracing():
    key = os.environ.get("NEATLOGS_API_KEY")
    if not key:
        print("warning: NEATLOGS_API_KEY not set, running without tracing", file=sys.stderr)
        return False
    try:
        neatlogs.init(api_key=key, endpoint="https://ingest.neatlogs.com",
                      workflow_name="fresh-clone-check")
        return True
    except Exception as e:  # tracing must never fail the run
        print(f"warning: neatlogs init failed: {scrub(str(e))}", file=sys.stderr)
        return False


def run_agent(box, repo, sha):
    """Clone, then drive the repair graph. Returns the final graph state."""
    if not box.clone(repo, sha):
        return {"status": "fail", "detail": "clone failed", "attempts": []}
    url = os.environ.get("MODEL_GATEWAY_URL", "")
    model = GatewayChat(url=url)
    graph = build_graph(box, model, time.monotonic() + BUDGET_S)
    config = {"callbacks": [neatlogs.langchain_handler()]} if TRACING else {}
    state = graph.invoke({"attempts": []}, config=config)
    state["model_calls"] = model.calls
    return state


def execute(repo, sha, subdir, root):
    started = time.time()
    run_id = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + sha[:7]
    record = {"run_id": run_id, "repo": repo, "sha": sha, "path": subdir, "image": IMAGE,
              "agent_version": __version__, "started": started,
              "agent": {"steps": []}, "verifier": {"steps": []}}
    root.set_attribute("repo", repo)
    root.set_attribute("sha", sha)
    root.set_attribute("agent_version", __version__)
    out = Path("runs") / run_id
    out.mkdir(parents=True, exist_ok=True)
    created, result = [], "fail"
    try:
        ensure_network()
        name = f"resurgo-{run_id.lower()}-agent"
        start_container(name, run_id)
        created.append(name)
        box = Box(name, "agent", subdir)
        state = run_agent(box, repo, sha)
        patch = box.diff() if state.get("status") == "passed" or box.touched else ""
        if patch:
            (out / "fix.patch").write_text(patch)
        record["agent"] = {"passed": state.get("status") == "passed", "status": state.get("status"),
                           "detail": scrub(state.get("detail", "")), "package_manager": box.pm,
                           "rules_fired": state.get("rules_fired", []),
                           "attempts": state.get("attempts", []), "steps": box.steps}
        record["model_calls"] = state.get("model_calls", [])
        result = state.get("status", "fail")
        if result == "passed":
            vname = f"resurgo-{run_id.lower()}-verifier"
            start_container(vname, run_id)
            created.append(vname)
            vbox = Box(vname, "verifier", subdir)
            ok = vbox.clone(repo, sha)
            if ok and patch:
                vbox.apply_patch(patch)
            ok = ok and vbox.pipeline() is None
            record["verifier"] = {"passed": ok, "steps": vbox.steps}
            result = ("fixed" if patch else "pass") if ok else "unverified"
    except Exception as e:
        record["error"] = scrub(str(e))
    finally:
        for name in created:
            docker("rm", "-f", name)  # only containers this run created
    record["ended"] = time.time()
    record["result"] = result
    root.set_attribute("result", result)
    (out / "result.json").write_text(json.dumps(record, indent=2, default=str))
    calls = record.get("model_calls", [])
    print(f"{run_id} {repo}@{sha} path={subdir or '.'} result={result} "
          f"attempts={len(record['agent'].get('attempts', []))} model_calls={len(calls)} "
          f"{round(record['ended'] - started)}s {record['agent'].get('detail', '')}".rstrip())
    return 0 if result in ("pass", "fixed") else 1


def main(repo, sha, subdir=""):
    global TRACING
    load_dotenv()
    TRACING = init_tracing()
    try:
        with tool_span_root() as root:
            return execute(repo, sha, subdir.strip("/"), root)
    finally:
        if TRACING:
            try:
                neatlogs.flush()
                neatlogs.shutdown()
            except Exception as e:
                print(f"warning: neatlogs flush failed: {scrub(str(e))}", file=sys.stderr)


if __name__ == "__main__":
    ap = argparse.ArgumentParser(prog="python -m resurgo.run")
    ap.add_argument("repo", help="owner/repo")
    ap.add_argument("sha")
    ap.add_argument("--path", default="", help="project subdirectory inside the repo")
    args = ap.parse_args()
    sys.exit(main(args.repo, args.sha, args.path))
"""LangGraph repair loop: run -> (rules) -> diagnose -> propose -> apply -> run ...

Only the model-facing and decision logic lives here; container work is done by `box`
(see run.Box). The neatlogs handler is attached by the caller at graph invoke, so the nodes
below create no spans of their own.
"""
import json
import re
import time
from typing import TypedDict

from langchain_core.messages import AIMessage, HumanMessage, SystemMessage
from langchain_core.runnables import RunnableConfig
from langgraph.graph import END, START, StateGraph

from resurgo.gateway import MAX_REQUEST_BYTES, ModelLimited, ModelUnavailable
from resurgo.rules import LOCKFILES, apply_rules

MAX_ATTEMPTS = 4          # fix attempts per repo, a rule candidate counts as one
BUDGET_S = 15 * 60        # wall clock per repo for the loop
CONFIG_NAMES = {".nvmrc", ".node-version", ".npmrc", ".yarnrc", ".yarnrc.yml",
                "pnpm-workspace.yaml", ".tool-versions"}
PACKAGE_JSON_KEYS = {"packageManager", "engines", "volta", "pnpm", "overrides", "resolutions",
                     "devEngines"}
LOCKFILE_NAMES = {n for n, _ in LOCKFILES}
MANIFEST_BYTES = 12_000

SYSTEM = """You repair a Node.js project that fails on a fresh machine (Node 24, corepack, \
the latest package manager). Diagnose the failing step from the command, exit code and output, \
then reply with ONE JSON object and nothing else:
{"kind": "config" | "code", "files": [{"path": "<path relative to the repo root>", \
"content": "<complete new file content>"}], "rationale": "<why this fixes it>", \
"confidence": <number from 0 to 1>}
kind "config": only version pins and tool settings: .nvmrc, .node-version, .npmrc, .yarnrc, \
.yarnrc.yml, pnpm-workspace.yaml, and in package.json only the packageManager, engines, volta, \
pnpm (for example onlyBuiltDependencies), overrides, resolutions and devEngines fields. Give \
complete file contents; keep every other package.json field unchanged. To regenerate a lockfile, \
list it with content "". These are applied and re-run.
kind "code": any change to source, scripts or dependencies. These are NOT applied; they are \
recorded for human approval. Prefer a config fix when one exists."""


class State(TypedDict, total=False):
    failure: dict
    attempts: list
    rules_tried: bool
    rule_applied: bool
    rules_fired: list
    system: str
    user: str
    raw: str
    proposal: dict
    reasked: bool
    status: str
    detail: str


def parse_proposal(raw):
    """(proposal, error). Strict JSON; a leading ```json fence is tolerated."""
    text = raw.strip()
    m = re.match(r"^```(?:json)?\s*(.*?)\s*```$", text, re.S)
    if m:
        text = m.group(1)
    try:
        p = json.loads(text)
    except ValueError as e:
        return None, f"not valid JSON: {e}"
    if not isinstance(p, dict):
        return None, "top level must be a JSON object"
    if p.get("kind") not in ("config", "code"):
        return None, 'kind must be "config" or "code"'
    files = p.get("files")
    if not isinstance(files, list):
        return None, "files must be a list"
    for f in files:
        if not (isinstance(f, dict) and isinstance(f.get("path"), str) and isinstance(f.get("content"), str)):
            return None, 'each file needs a string "path" and a string "content"'
        parts = f["path"].split("/")
        if f["path"].startswith("/") or ".." in parts or parts[0] == ".git" or not f["path"]:
            return None, f"unsafe path {f['path']!r}"
    if not isinstance(p.get("rationale"), str):
        return None, "rationale must be a string"
    c = p.get("confidence")
    if isinstance(c, bool) or not isinstance(c, (int, float)) or not 0 <= c <= 1:
        return None, "confidence must be a number between 0 and 1"
    return p, None


def config_problem(box, proposal):
    """Why this config proposal cannot be applied automatically, or None."""
    for f in proposal["files"]:
        name = f["path"].rsplit("/", 1)[-1]
        if name in LOCKFILE_NAMES:
            if f["content"] != "":
                return f"{f['path']}: a lockfile can only be regenerated (content \"\")"
        elif name == "package.json":
            old = box.read(f["path"])
            try:
                old, new = json.loads(old or "{}"), json.loads(f["content"])
            except ValueError:
                return f"{f['path']}: not valid JSON"
            changed = {k for k in old.keys() | new.keys() if old.get(k) != new.get(k)}
            if changed - PACKAGE_JSON_KEYS:
                return f"{f['path']}: changes {sorted(changed - PACKAGE_JSON_KEYS)}, which is not config"
        elif name not in CONFIG_NAMES:
            return f"{f['path']}: not a config file"
    return None


def build_prompt(box, failure, attempts):
    """User message: command, exit code, manifests, history, then as much output tail as fits
    under the request limit."""
    parts = [f"Failing step: {failure['step']}", f"Command: {failure['command']}",
             f"Exit code: {failure['exit_code']}", f"Environment: {box.versions or 'unknown'}",
             f"Project path in repo: {box.subdir or '.'}"]
    if attempts:
        parts.append("Previous attempts (do not repeat what failed):")
        for a in attempts:
            parts.append(f"- {a['source']} {a['kind']} {a['files']}: {a.get('result')}")
    names = ["package.json", ".nvmrc", ".node-version", ".npmrc", ".yarnrc.yml",
             "pnpm-workspace.yaml"] + sorted(LOCKFILE_NAMES)
    found = box.read_many([p for n in names for p in {box.rel(n), n}])
    seen = set()
    for name in names:
        for path in (box.rel(name), name):
            if path in seen:
                continue
            seen.add(path)
            text = found.get(path)
            if text is None:
                continue
            if name in LOCKFILE_NAMES:
                text = "\n".join(text.splitlines()[:30]) + "\n[lockfile truncated]"
            parts.append(f"--- {path} ---\n{text[:MANIFEST_BYTES]}")
    head = "\n\n".join(parts) + "\n\n--- output tail ---\n"
    # leave room for a re-ask (the reply plus an error line) inside the same limit
    room = MAX_REQUEST_BYTES - len((SYSTEM + head).encode()) - 8_000
    tail = box.last_out.encode()[-max(room, 0):].decode(errors="ignore")
    return head + tail


def build_graph(box, model, deadline):
    def over_budget():
        return time.monotonic() > deadline

    def applied(state):
        return [a for a in state.get("attempts", []) if a["status"] == "applied"]

    def settle(attempts, result):
        """Record how the last applied attempt turned out once it has been re-run."""
        if attempts and attempts[-1]["status"] == "applied" and attempts[-1].get("result") is None:
            attempts = attempts[:-1] + [{**attempts[-1], "result": result}]
        return attempts

    def run(state):
        if over_budget():
            return {"status": "budget_exhausted", "detail": f"{BUDGET_S // 60} minute budget used"}
        failure = box.pipeline()
        attempts = settle(state.get("attempts", []),
                          "passed" if failure is None else f"failed at {failure['step']}")
        if failure is None:
            return {"status": "passed", "failure": {}, "attempts": attempts}
        out = {"failure": failure, "attempts": attempts}
        if failure["step"] not in ("install", "build"):
            out.update(status="fail", detail=f"{failure['step']} failed; not a fixable step")
        elif len(applied({"attempts": attempts})) >= MAX_ATTEMPTS:
            out.update(status="budget_exhausted", detail=f"{MAX_ATTEMPTS} fix attempts used")
        return out

    def rules(state):
        fired, fixes = apply_rules(box.rule_files())
        attempts = list(state.get("attempts", []))
        if fixes:
            paths = box.write({box.rel(n): c for n, c in fixes.items()})
            attempts.append({"source": "rule", "kind": "config", "files": paths,
                             "rationale": "; ".join(f"{r['rule']}: {r['value']} from {r['source']}"
                                                    for r in fired),
                             "confidence": None, "status": "applied", "result": None})
        return {"rules_tried": True, "rule_applied": bool(fixes), "rules_fired": fired,
                "attempts": attempts}

    def ask(messages, config):
        return model.invoke(messages, config).content

    def failed_model(e):
        if isinstance(e, ModelLimited):
            return {"status": "model_limited", "detail": str(e)}
        return {"status": "model_unavailable", "detail": str(e)}

    def diagnose(state, config: RunnableConfig):
        if over_budget():
            return {"status": "budget_exhausted", "detail": f"{BUDGET_S // 60} minute budget used"}
        user = build_prompt(box, state["failure"], state.get("attempts", []))
        try:
            raw = ask([SystemMessage(SYSTEM), HumanMessage(user)], config)
        except (ModelLimited, ModelUnavailable) as e:
            return failed_model(e)
        return {"system": SYSTEM, "user": user, "raw": raw, "reasked": False}

    def propose(state, config: RunnableConfig):
        proposal, err = parse_proposal(state["raw"])
        if err:
            msgs = [SystemMessage(state["system"]), HumanMessage(state["user"]),
                    AIMessage(state["raw"][:4000]),
                    HumanMessage(f"That reply was rejected: {err}. "
                                 "Reply again with only the JSON object.")]
            try:
                raw = ask(msgs, config)
            except (ModelLimited, ModelUnavailable) as e:
                return failed_model(e)
            proposal, err = parse_proposal(raw)
            if err:
                return {"status": "invalid_proposal", "detail": err, "raw": raw}
            return {"proposal": {**proposal, "recovered_from_invalid_json": True}, "raw": raw}
        return {"proposal": proposal}

    def apply(state):
        p = state["proposal"]
        attempts = list(state.get("attempts", []))
        entry = {"source": "model", "kind": p["kind"], "files": [f["path"] for f in p["files"]],
                 "rationale": p["rationale"], "confidence": p["confidence"], "result": None,
                 "recovered_from_invalid_json": p.get("recovered_from_invalid_json", False)}
        problem = None
        if p["kind"] == "code":
            problem = "code fix, not applied in this milestone"
        elif not p["files"]:
            problem = "config proposal has no files"
        else:
            problem = config_problem(box, p)
        if problem:
            entry.update(status="needs_approval", result=problem, files_content=p["files"])
            status = "needs_approval" if p["files"] else "fail"
            return {"attempts": attempts + [entry], "status": status, "detail": problem}
        box.write({f["path"]: f["content"] for f in p["files"] if f["content"] != ""})
        box.remove([f["path"] for f in p["files"] if f["content"] == ""])
        entry["status"] = "applied"
        return {"attempts": attempts + [entry]}

    def after_run(state):
        if state.get("status"):
            return END
        return "diagnose" if state.get("rules_tried") else "rules"

    g = StateGraph(State)
    for name, fn in [("run", run), ("rules", rules), ("diagnose", diagnose),
                     ("propose", propose), ("apply", apply)]:
        g.add_node(name, fn)
    g.add_edge(START, "run")
    g.add_conditional_edges("run", after_run, ["rules", "diagnose", END])
    g.add_conditional_edges("rules", lambda s: "run" if s["rule_applied"] else "diagnose",
                            ["run", "diagnose"])
    g.add_conditional_edges("diagnose", lambda s: END if s.get("status") else "propose",
                            ["propose", END])
    g.add_conditional_edges("propose", lambda s: END if s.get("status") else "apply",
                            ["apply", END])
    g.add_conditional_edges("apply", lambda s: END if s.get("status") else "run", ["run", END])
    return g.compile()

"""Deterministic toolchain rules. No model call: each rule is a fix candidate (files to write)
that the verifier checks like any other fix.

The fresh-machine baseline is Node 24 plus whatever corepack resolves, honouring only `.nvmrc`
and the `packageManager` field. Rules write those two files when the repo declares its
toolchain somewhere the baseline does not read (engines, .node-version, volta, a lockfile).
"""
import json
import re

BASELINE_NODE = 24
NODE_MAJORS = [24, 22, 20, 18, 16, 14, 12]
LTS_NAMES = {"krypton": 24, "jod": 22, "iron": 20, "hydrogen": 18, "gallium": 16,
             "fermium": 14, "erbium": 12}
# ponytail: the last release of each major; the packageManager field needs an exact version.
PM_VERSIONS = {
    "pnpm": {5: "5.18.10", 6: "6.35.1", 7: "7.33.7", 8: "8.15.9", 9: "9.15.9"},
    "yarn": {1: "1.22.22", 2: "2.4.3", 3: "3.8.7", 4: "4.9.2"},
    "npm": {6: "6.14.18", 7: "7.24.2", 8: "8.19.4", 9: "9.9.4", 10: "10.9.2"},
}
LOCKFILES = [("pnpm-lock.yaml", "pnpm"), ("yarn.lock", "yarn"), ("package-lock.json", "npm")]
# Files that rules read; the caller supplies their contents (None when absent).
RULE_FILES = ["package.json", ".nvmrc", ".node-version"] + [n for n, _ in LOCKFILES]


def parse_major(text):
    """Node major from the contents of .nvmrc / .node-version / a volta pin."""
    t = (text or "").strip().lower().lstrip("v")
    if t in ("node", "stable", "lts/*"):
        return BASELINE_NODE
    m = re.match(r"(\d+)", t)
    if m:
        return int(m.group(1))
    m = re.match(r"lts/(\w+)", t)
    return LTS_NAMES.get(m.group(1)) if m else None


def _version(tok):
    """'20.x' -> (20, None, None); '20.1.2' -> (20, 1, 2); '*' -> (None, None, None)."""
    parts = tok.lstrip("v=").split("-")[0].split(".")
    nums = [int(p) if p.isdigit() else None for p in parts[:3]]
    return tuple(nums + [None] * (3 - len(nums)))


def _comparator(op, tok, v):
    lo = tuple(x or 0 for x in _version(tok))
    parts = _version(tok)
    known = sum(p is not None for p in parts)
    if known == 0:
        return True
    bump = [(lo[0] + 1, 0, 0), (lo[0], lo[1] + 1, 0), (lo[0], lo[1], lo[2] + 1)][known - 1]
    if op in ("", "="):
        return lo <= v < bump
    if op == ">=":
        return v >= lo
    if op == ">":
        return v >= bump
    if op == "<":
        return v < lo
    if op == "<=":
        return v < bump
    if op == "~":
        return lo <= v < ([(lo[0] + 1, 0, 0), (lo[0], lo[1] + 1, 0)][known > 1])
    if op == "^":
        if lo[0] > 0 or known == 1:
            up = (lo[0] + 1, 0, 0)
        elif lo[1] > 0 or known == 2:
            up = (0, lo[1] + 1, 0)
        else:
            up = (0, 0, lo[2] + 1)
        return lo <= v < up
    return True  # unknown operator: do not exclude


def range_allows(rng, major):
    """True if some version of this Node major satisfies the semver range `rng`."""
    probes = {(major, 0, 0), (major, 9999, 0)}
    for m in re.finditer(r"(\d+)(?:\.(\d+))?(?:\.(\d+))?", rng):
        if int(m.group(1)) == major:
            probes.add((major, int(m.group(2) or 0), int(m.group(3) or 0)))
    for alt in rng.split("||"):
        alt = re.sub(r"(>=|<=|>|<|=|\^|~)\s+", r"\1", alt)
        toks = [t for t in alt.split() if t != "-"] or ["*"]
        ok = []
        for v in probes:
            ok.append(all(_comparator(*re.match(r"(>=|<=|>|<|=|\^|~)?(.*)", t).groups(""), v)
                          for t in toks))
        if any(ok):
            return True
    return False


def node_major(files):
    """(major, source) from engines.node, .nvmrc, .node-version or volta, in that order."""
    try:
        pkg = json.loads(files.get("package.json") or "{}")
    except ValueError:
        pkg = {}
    engines = (pkg.get("engines") or {}).get("node")
    if isinstance(engines, str):
        for major in NODE_MAJORS:
            if range_allows(engines, major):
                return major, f"package.json engines.node {engines!r}"
    for name in (".nvmrc", ".node-version"):
        major = parse_major(files.get(name))
        if major:
            return major, name
    volta = (pkg.get("volta") or {}).get("node")
    major = parse_major(volta) if isinstance(volta, str) else None
    return (major, f"package.json volta.node {volta!r}") if major else (None, None)


def package_manager(files):
    """(name, exact_version, source) from the packageManager field, else the lockfile format."""
    try:
        pkg = json.loads(files.get("package.json") or "{}")
    except ValueError:
        pkg = {}
    declared = pkg.get("packageManager")
    if isinstance(declared, str) and "@" in declared:
        name, _, ver = declared.partition("@")
        return name, ver.split("+")[0], "packageManager field"
    text = files.get("pnpm-lock.yaml")
    if text is not None:
        m = re.search(r"lockfileVersion:\s*['\"]?(\d+)\.(\d+)", text)
        if m:
            v = (int(m.group(1)), int(m.group(2)))
            major = {(5, 0): 5, (5, 1): 5, (5, 2): 5, (5, 3): 6, (5, 4): 7, (6, 0): 8, (6, 1): 8}.get(v)
            if major:
                return "pnpm", PM_VERSIONS["pnpm"][major], f"pnpm-lock.yaml lockfileVersion {v[0]}.{v[1]}"
        return None
    text = files.get("yarn.lock")
    if text is not None:
        m = re.search(r"^__metadata:\s*\n\s+version:\s*(\d+)", text, re.M)
        if not m:
            return "yarn", PM_VERSIONS["yarn"][1], "yarn.lock classic format"
        major = 2 if int(m.group(1)) <= 4 else 3 if int(m.group(1)) <= 6 else 4
        return "yarn", PM_VERSIONS["yarn"][major], f"yarn.lock berry metadata version {m.group(1)}"
    text = files.get("package-lock.json")
    if text is not None:
        m = re.search(r'"lockfileVersion":\s*(\d+)', text)
        if m and int(m.group(1)) == 1:
            return "npm", PM_VERSIONS["npm"][6], "package-lock.json lockfileVersion 1"
    return None


def _dump_package_json(text, pkg):
    indent = "\t" if re.search(r'^\t"', text, re.M) else 2
    return json.dumps(pkg, indent=indent, ensure_ascii=False) + ("\n" if text.endswith("\n") else "")


def apply_rules(files):
    """Return (fired, fixes). `fired` lists each rule that changes the toolchain, with its
    source and value; `fixes` maps path -> new file content."""
    fired, fixes = [], {}
    major, source = node_major(files)
    current = parse_major(files.get(".nvmrc")) or BASELINE_NODE
    if major and major != current:
        fired.append({"rule": "node-major", "source": source, "value": str(major)})
        fixes[".nvmrc"] = f"{major}\n"
    pm = package_manager(files)
    pkg_text = files.get("package.json")
    if pm and pkg_text and pm[2] != "packageManager field":
        try:
            pkg = json.loads(pkg_text)
        except ValueError:
            pkg = None
        if isinstance(pkg, dict):
            pkg["packageManager"] = f"{pm[0]}@{pm[1]}"
            fired.append({"rule": "package-manager", "source": pm[2], "value": f"{pm[0]}@{pm[1]}"})
            fixes["package.json"] = _dump_package_json(pkg_text, pkg)
    return fired, fixes
from resurgo.run import detect_pm


def test_detect_pm():
    assert detect_pm(["package.json", "pnpm-lock.yaml"]) == "pnpm"
    assert detect_pm(["yarn.lock"]) == "yarn"
    assert detect_pm(["package-lock.json"]) == "npm"
    assert detect_pm(["package.json"]) is None


if __name__ == "__main__":
    test_detect_pm()
    print("ok")
from resurgo.rules import apply_rules, node_major, package_manager


def test_rules():
    # engines.node picks the highest LTS major that satisfies the range
    assert node_major({"package.json": '{"engines":{"node":"^20.19 || ^22"}}'})[0] == 22
    assert node_major({"package.json": '{"engines":{"node":">=18"}}'})[0] == 24
    assert node_major({".nvmrc": "v20.11.0\n"})[0] == 20
    # lockfile format picks the package manager when packageManager is absent
    assert package_manager({"pnpm-lock.yaml": "lockfileVersion: '6.0'\n"})[:2] == ("pnpm", "8.15.9")
    assert package_manager({"pnpm-lock.yaml": "lockfileVersion: '9.0'\n"}) is None
    assert package_manager({"yarn.lock": "# yarn lockfile v1\n"})[:2] == ("yarn", "1.22.22")
    assert package_manager({"yarn.lock": "__metadata:\n  version: 8\n"})[:2] == ("yarn", "4.9.2")
    assert package_manager({"package-lock.json": '{"lockfileVersion": 1}'})[:2] == ("npm", "6.14.18")
    # rules become file fixes; an existing .nvmrc that already matches is left alone
